"id": "eq-0004",
"nomFr": "Patchs réfléchissants",
"nomEn": "Reflective Pads",
"effet": "Idée farfelue de nombreux tireurs d'élite utilisant des blasters, ces patchs ont été commercialisés par plusieurs petites entreprises spécialisées en armes 'de niche'. Largement tournées en ridicule, ces petites entités jurent par ces patchs réfléchissants et assurent aux acheteurs qu'ils reflètent parfaitement et intégralement un tir de blaster avec toute sa puissance. Le problème est que le niveau de compétence requis pour les utiliser les rend en pratique quasiment inutiles. Avec suffisamment de réflexes et de ruse, cependant, un tireur d'élite habile peut en tirer bon parti pour tirer depuis un couvert. En tant qu'incident sur son tour, le personnage peut effectuer un test de Perception de difficulté Difficile pour repérer un emplacement à portée courte où lancer le patch collant, ce qui lui permettra d'obtenir un visuel sur une cible jusqu'à portée moyenne malgré un couvert. En tant que manœuvre, sur un test réussi, il peut effectuer un test de Distance (Léger) de difficulté Moyenne pour lancer le patch à l'endroit indiqué. Une fois le patch placé avec succès, le personnage peut attaquer sa cible désirée derrière son couvert, mais la difficulté de l'attaque est augmentée et améliorée une fois. Chaque test utilisant ces patchs gagne un dé de complication pour chaque résultat de menace généré lors d'un test précédent, et la difficulté des tests suivants est augmentée dès trois résultats de menace ou un résultat de désespoir.",
