"nomFr": "Gantelets de Marka Ragnos",
"nomEn": "Gauntlets of Marka Ragnos",
"effet": "Confectionnés à partir d'écailles noires d'une créature inconnue, ces gants ont été portés par l'un des Sith les plus puissants de son époque. La rage et la fureur que Marka Ragnos y a imprégnées en abattant d'innombrables Jedi avec son sabre laser peuvent encore s'en dégager. Leur présence obscure tente et corrompt les utilisateurs de la Force qui les portent, les attirant lentement vers le côté obscur. Un personnage sensible à la Force les portant ajoute un résultat de succès et un résultat d'avantage à tout test de Sabre laser. Lorsqu'il a l'occasion d'incapacité létalement un ennemi, il doit réussir un test de Discipline de difficulté Difficile pour résister à cette tentation. Au début d'une session, un personnage possédant les gantelets gagne 1 point de Conflit.",
