"nomEn": "Remote DVI Activator (Long Range)",
"effet": "Utile pour ceux ayant besoin de filer rapidement, un contrôleur d'activation à distance (aussi appelé « appel de rappel ») est un petit appareil portatif pouvant être porté au poignet ou rangé dans une poche. Les modèles bon marché se contentent d'activer les moteurs du véhicule ou du vaisseau à moins de cinq kilomètres de distance et d'effectuer de simples vérifications pré-vol, permettant au pilote de décoller immédiatement. Les modèles plus avancés peuvent faire venir un véhicule ou un vaisseau, bien que le pilote automatique ne soit capable que de manœuvres simples, pouvant être compliquées par les conditions météorologiques et d'autres obstacles. Certains modèles peuvent être utilisés pour piloter à distance un véhicule ou un vaisseau via circuit esclave, bien que cela nécessite un test de Pilotage de difficulté Redoutable. Pour la variante courte portée, le prix est de 300 crédits et la rareté de 4.",
