"nomFr": "Transmetteur de voix falsifiée",
"nomEn": "False Voice Transmitter",
"effet": "Depuis des années, une multitude d'organisations criminelles et de résistance ont utilisé des dispositifs artisanaux connus sous le nom de transmetteurs de voix falsifiée (FVT) pour tromper l'Empire. Lorsqu'il se fait passer pour un autre individu à l'aide d'un FVT, l'utilisateur peut majorer une fois l'aptitude de ses tests de Charme, Coercition, Tromperie, Commandement et Négociation.",
