"id": "eq-0034",
"nomFr": "Télécommande d'artillerie",
"nomEn": "Artillery Remote",
"effet": "Les emplacements d'artillerie sont des cibles prioritaires lors des assauts, et les pertes parmi les servants sont en conséquence élevées. Un personnage peut relier une arme d'Artillerie unique à une télécommande d'artillerie Atgar avec un test d'Informatique de difficulté Difficile (Moyenne si l'arme est un modèle Atgar). En cas de réussite, l'arme gagne la qualité Imprécis 2, et le porteur de la télécommande peut la tirer à distance, jusqu'à portée moyenne.",
