"nomEn": "Cirenian Communications Pioneer Long-Range Transceiver",
"effet": "Également appelés transmetteurs subspatiaux, les hypertransmetteurs servent à des communications interstellaires quasi instantanées, plus rapides que la lumière. Ils peuvent envoyer des messages sur plusieurs années-lumière ; des modèles puissants comme celui-ci peuvent transmettre jusqu'à 100 années-lumière. Des hypertransmetteurs portables plus petits existent également, avec une portée d'environ 25 années-lumière.",
