"nomFr": "Baume apaisant",
"nomEn": "Calming Salve",
"effet": "En frottant ce baume sur la peau, un être sensible s'ouvre à la Force Vivante qui l'entoure. Une fois par session, en tant qu'action, un personnage sensible à la Force peut utiliser le Baume apaisant et effectuer un test de pouvoir de la Force. Il peut dépenser un Point de Force généré par des résultats de Point lumineux pour récupérer un point de fatigue par Point de Force ainsi dépensé.",
