"id": "eq-0040",
"nomFr": "Bras de chargement lourd CZ-88",
"nomEn": "CZ-88 Heavy Loader Arm",
"effet": "Le modèle de chargeur lourd CZ-88 produit par Czerka est un équipement polyvalent utilisé pour tout, du transport de fret à la récupération d'épaves en passant par le remplacement de plaques de coque endommagées sur des vaisseaux. Il inclut un cerveau de droïde monotâche capable d'effectuer des tests pour soulever des objets (Athlétisme 1, Vigueur 5 ; sans assistance, il lance un dé de maîtrise et quatre dés d'aptitude pour ces tests). Certains récupérateurs l'installent directement sur leurs vaisseaux ou véhicules pour faciliter la récupération de ferraille et d'autres composants, comme alternative bon marché à un projecteur de rayon tracteur. Il peut être installé sur un véhicule de gabarit 3 ou plus en tant que modification et utilise un point d'ancrage ; les occupants peuvent alors s'en servir pour charger ou décharger des objets (et d'autres actions, à la discrétion du MJ) sans débarquer.",
