"nomEn": "Model 40 Field Repulsor Hoist",
"effet": "Le palan à répulsion de terrain Modèle 40 est né d'un dispositif de levage de véhicule improvisé (autrement dit, bricolé), conçu par la mécanicienne de l'Armée de l'Alliance Lidiah Alexakis. (lot de 6) Le Modèle 40 peut soulever un véhicule jusqu'au gabarit 4 à deux mètres du sol. Une fois suspendu, le véhicule peut être poussé, tiré ou pivoté (lentement) dans n'importe quelle direction via un test d'Athlétisme dont la difficulté est égale au gabarit du véhicule.",
