"id": "eq-0052",
"nomFr": "Déguisement cybernétique",
"nomEn": "Cyber Disguise",
"effet": "Un implant de déguisement cybernétique se compose d'une série de systèmes intégrés sous la peau d'un individu, lui permettant de modifier son apparence. Il confère à un personnage tous les avantages d'un kit de déguisement standard, ainsi que deux rangs du talent Indiscernable. Modifier des traits généraux (couleur des yeux, des cheveux, pilosité faciale) prend un à trois rounds ; des déguisements plus élaborés peuvent prendre des minutes, voire des heures. Pour prendre l'apparence d'un individu précis, l'utilisateur doit d'abord étudier sa cible en détail, puis réussir un test de Tromperie de difficulté Difficile pour régler le déguisement. Il ne peut pas modifier la forme ou la taille générale d'un être, ni ajouter ou retirer des membres, ni se faire passer pour un membre d'une autre espèce. À la discrétion du MJ, il pourrait servir à imiter des espèces très proches de celle de l'utilisateur : un humain pourrait ainsi se faire passer pour un Chiss ou un Pantoran, par exemple.",
"cout": 18000,
"coutTxt": "18000",
