"nomFr": "Neuroparalysant synthétique",
"nomEn": "Synthetic Neuroparalytic",
"effet": "Les poisons qui paralysent une cible tout en laissant intactes ses fonctions cognitives supérieures sont difficiles à créer et à administrer. Ce poison ne peut être introduit dans une cible que par injection, comme avec un applicateur ou une fléchette. Toute dose, quelle que soit sa taille, nécessite un test de Résilience de difficulté Difficile pour être résistée. Le poison immobilise la cible pendant trois rounds si elle échoue au test. De plus, chaque résultat de menace peut être dépensé pour infliger 1 point de tension à la cible. Un résultat de désespoir peut être dépensé pour faire retester la cible contre le poison lors du round suivant, celui-ci restant dans son organisme.",
