"effet": "La neurotoxine synthétique est un poison général produit synthétiquement, souvent illégalement, sur des centaines de mondes. Ce poison peut être introduit dans le corps de la cible par aérosolisation, ingestion alimentaire, ou injection à l'aide d'un applicateur ou d'une fléchette. Résister à une seule dose nécessite un test de Résilience de difficulté Moyenne, tandis que deux doses ou plus combinées en une seule application nécessitent un test de Résilience de difficulté Difficile. Le poison inflige 5 blessures si la cible échoue au test. Chaque résultat de menace généré peut être dépensé pour infliger 1 point de tension à la cible, l'effort de lutter contre le poison la submergeant. Enfin, un résultat de désespoir peut être dépensé pour faire retester la cible contre le poison lors du round suivant, celui-ci restant dans son organisme.",
