"nomEn": "Gunjack Spice (100 Dose Cargo Container)",
"effet": "Synthétisé à partir d'un mélange fortement concentré de méthylpénatox, de glucose et de produits chimiques inotropes, le gunjack augmente nettement la force de son utilisateur, au prix d'une coordination motrice réduite, d'une acuité mentale diminuée et de graves risques sanitaires à long terme. Une dose augmente la caractéristique de Vigueur de l'utilisateur de 1 (jusqu'à un maximum de 6) jusqu'à la fin de la scène ou de la rencontre de combat. De plus, chaque dose consommée majore une fois la difficulté des tests d'Agilité, d'Intellect et de Ruse du personnage jusqu'à la fin de la session de jeu.",
