"effet": "L'épice yaladai est un stimulant prisé et coûteux, valant plusieurs fois le prix de drogues plus communes, comme le glitterstim, sur le marché noir. Les effets de l'épice yaladai durent le temps d'une rencontre. Lorsqu'un personnage sous l'effet de l'épice subit de la tension, il en subit trois de moins, jusqu'à un minimum de un. Ceci ne s'applique pas à la perte de tension volontaire. De plus, un utilisateur de la Force sous l'effet de l'épice yaladai peut ajouter un dé de Force à tout test de pouvoir de la Force qu'il effectue. Cependant, ce faisant, l'épice double toute tension et tout Conflit subis pour avoir utilisé un point d'Obscurité afin de générer un point de Force.",
