"effet": "Un brouilleur de capteurs portable. Il s'agit d'un dispositif autonome n'ayant pas besoin d'être couplé à un capteur. L'appareil est similaire à une suite CME, mais bien moins puissant. Sa portée est très réduite, ce qui le destine généralement à dissimuler un avant-poste ou à un usage limité au combat planétaire. Un brouilleur de capteurs ajoute deux dés de complication à toutes les tentatives de détection à portée moyenne planétaire lorsqu'il est activé. Cependant, le brouilleur provoque des Émissions amplifiées pour les tentatives dirigées contre lui-même.",
