"nomFr": "Drone de reconnaissance Arakyd Industries",
"nomEn": "Arakyd Industries Recon Remote",
"effet": "Petits drones sphériques équipés de générateurs répulsorlift miniaturisés, utilisés par les militaires et les agents de sécurité pour la reconnaissance et la surveillance. Le drone a à peu près la taille d'un fruit shuura (gabarit 0) et peut se déplacer à 20 km/h. Il dispose de capteurs visuels à 360 degrés avec vision nocturne et peut transmettre des données à un récepteur distant jusqu'à 20 kilomètres. L'unité de contrôle peut surveiller simultanément jusqu'à quatre de ces drones. Le modèle d'Arakyd Industries peut fonctionner 24 heures avant de devoir être rechargé.",
