"effet": "Les détecteurs de mines sont des scanners portatifs spécialisés conçus pour localiser des mines antipersonnel et antivéhicule enfouies ou dissimulées. Utiliser un détecteur de mines pour localiser des mines dissimulées nécessite un test d'Informatique de difficulté Difficile ou un test de Vigilance de difficulté Moyenne, avec les modificateurs appropriés selon les conditions environnementales (météo, végétation, terrain accidenté ou composition du sol). En cas de réussite, toutes les mines et autres engins explosifs à portée moyenne sont révélés à l'utilisateur.",
