"id": "eq-0127",
"nomFr": "Fob de pistage",
"nomEn": "Tracking Fob",
"effet": "L'un des avantages de l'affiliation à la Guilde des chasseurs de primes est l'usage gratuit des fobs de pistage. Il est rare que des chasseurs de primes non affiliés se voient offrir un tel dispositif d'assistance. Un fob peut être calibré sur le signal biométrique d'un individu en entrant son code de chaîne, fournissant des données de pistage à courte portée. Bien que cela facilite la traque des cibles, ces fobs sont limités par leur portée effective de 100 km. Il fonctionne comme une boussole, pointant vers l'individu programmé s'il se trouve à portée. Ils sont généralement prêtés aux chasseurs de primes pour la durée d'une traque. Certains individus choisissent simplement d'acheter leur propre fob à usage personnel, mais le programmer nécessite de connaître le code de chaîne de la cible désirée.",
