"nomFr": "Holo-scanner",
"nomEn": "Holoscanner",
"effet": "Utilisés dans les spatioports et les lieux à haute sécurité à travers la galaxie, les holo-scanners permettent de détecter la présence d'objets dangereux ou illégaux sans avoir à fouiller physiquement les individus ou les conteneurs de fret. Modèles incluant : le holo-scanner de qualité douanière BAS44, le holo-scanner HB-2 de Fabritech, le SecureScan 1500 de TaggeCo, le réseau de scan 7320/H de Neuro-Saav Technologies. Les holo-scanners réduisent de deux la difficulté des tests de Perception ou de Vigilance visant à découvrir des objets dissimulés sur une personne, dans un conteneur ou un véhicule. Un holo-scanner ne peut généralement pas scanner un objet ou un groupe d'objets dont l'encombrement dépasse le sien.",
