"id": "eq-0131",
"nomFr": "Lunettes de chasse",
"nomEn": "Hunting Goggles",
"effet": "Les lunettes de chasse sont un type de lunettes de repérage spécialement conçues pour aider les guides professionnels et les chasseurs à traquer leurs proies. Elles confèrent un dé d'aide aux tests de Perception effectués pour localiser une proie, et grâce à leur amplification et à leur amélioration de l'image, elles suppriment jusqu'à deux dés de complication imposés par la dissimulation, l'obscurité, le brouillard ou la brume lors des tests de Distance (Léger) et de Distance (Lourd).",
