"id": "eq-0132",
"nomFr": "Lunettes de détection d'armes",
"nomEn": "Weapon Detection Goggles",
"effet": "Un détecteur d'armes est un capteur spécialisé intégré à des lunettes, capable de détecter la présence d'explosifs, des cellules d'énergie utilisées dans les blasters, et des propulseurs chimiques utilisés dans les armes à projectiles, ainsi que de nombreux types d'armes de mêlée telles que couteaux, épées et matraques paralysantes. Un personnage utilisant des lunettes de détection d'armes peut ajouter jusqu'à deux dés d'aide aux tests de Perception lorsqu'il tente de trouver une arme dissimulée sur une personne.",
