"id": "eq-0134",
"nomFr": "Pack de capteurs à pénétration de sol de CryonCorp",
"nomEn": "CryonCorp Ground-Penetrating Sensor Pack",
"effet": "Autre suite de capteurs produite par CryonCorp, le GPSP est un puissant radar à pénétration de sol commercialisé auprès des entreprises d'exploration gazière et minière ainsi que des équipes de recherche et sauvetage agréées. Utiliser un GPSP ne nécessite pas de test de compétence, mais interpréter ses résultats peut en nécessiter un. Si le MJ le juge bon, il peut exiger un test d'Informatique pour comprendre exactement ce que le GPSP détecte.",
