"nomFr": "Masque démoniaque",
"nomEn": "Demon Mask",
"effet": "Chaque espèce et culture possède ses histoires effrayantes de monstres aux pouvoirs surnaturels. Un personnage sensible à la Force portant un masque démoniaque voit son seuil de blessure augmenter de 2 tant qu'il est un utilisateur du côté obscur de la Force. De plus, les personnages effectuant des tests de Discipline pour résister à la peur provoquée par un porteur de masque démoniaque ajoutent des dés de complication égaux à l'indice de Force de ce dernier.",
