"id": "eq-0144",
"nomFr": "Orbe de méditation vurk",
"nomEn": "Vurk Meditation Orb",
"effet": "Ces orbes sont des sphères d'obsidienne parfaites, d'environ 15 centimètres de diamètre. Étudier la sphère opaque permet à un Mystique de se concentrer intérieurement, laissant le monde derrière lui. Dans cet état, il ne voit que les connexions entre les êtres, n'entend que les murmures de la Force. Cette méditation dure au moins une heure, et pendant les 24 heures suivant cette méditation, il peut subir 2 points de tension pour ajouter un point de Force au résultat du prochain test visant à utiliser le pouvoir de la Force Altération ou Méditation de combat.",
