"id": "eq-0147",
"nomFr": "Boîte aux lettres morte",
"nomEn": "Data Dead Drop",
"effet": "Outil courant et relativement bon marché des agents infiltrés et des informateurs, une boîte aux lettres morte permet l'échange discret d'une puce de données ou d'un autre message codé. Modèles inclus : la capsule de sécurité Brennkeyes Syndicate, ainsi que d'innombrables modèles artisanaux. Pour trouver ce qui est caché dans une boîte aux lettres morte, un personnage doit réussir un test de Perception de difficulté Ardue. À la discrétion du MJ, un personnage non averti pourrait utiliser la Vigilance à la place.",
