"nomFr": "Casseur de serrure électronique",
"nomEn": "Electronic Lock Breaker",
"effet": "Que ce soit pour voler de rares trésors chez un collectionneur privé ou dans un musée, ou pour se procurer des armes ou du matériel médical dans des bases militaires au profit d'une résistance armée, agents et voleurs doivent souvent contourner des systèmes de sécurité physique. Modèles inclus : l'outil de crochetage « Skeleton Key » de Locris Syndicate Securities, le casseur de serrure électronique OutlawTech.",
