"nomFr": "Entraves explosives",
"nomEn": "Explosive Shackles",
"effet": "Méthode particulièrement intimidante et malveillante de sécuriser esclaves et prisonniers, les entraves explosives intègrent de petites charges létales destinées à dissuader toute tentative d'évasion. Modèles inclus : de nombreuses variantes. Retirer des entraves explosives sans la clé appropriée nécessite un test de Filouterie de difficulté Ardue. En cas d'échec, les entraves explosent, infligeant 10 blessures au porteur ainsi qu'à tout personnage à portée engagée (ceci ignore le seuil de dommage).",
