"id": "eq-0169",
"nomFr": "Outils de contrefaçon",
"nomEn": "Forgery Tools",
"effet": "Quels que soient le contexte ou la légitimité de la raison, des outils de contrefaçon de qualité, tels que des encres et instruments soigneusement conçus ou des dispositifs complexes de falsification d'accréditations, peuvent renforcer les talents innés d'un faussaire. Modèles inclus : la suite de confidentialité Goseia Heavy Industries Concern Executive, ainsi que d'innombrables modèles artisanaux (et illégaux).",
