"nomFr": "Perturbateur EMI",
"nomEn": "EMP Disruptor",
"effet": "De la taille d'un simple stylet, cette technologie miniaturisée contient une petite batterie capable de décharger une impulsion électromagnétique localisée n'affectant que les systèmes électroniques les plus proches. Initialement conçu pour les techniciens travaillant dans des espaces restreints pour des réparations de circuiterie, ce perturbateur a gagné en popularité auprès des groupes d'opérations spéciales et des éléments criminels les plus retors de la galaxie, pour faciliter les tentatives de piratage. Il peut être utilisé une fois pour mettre silencieusement hors service un système électronique (serrure électrique, caméra, droïde de gabarit 0) à portée engagée, comme s'il possédait la qualité Ionisant.",
