"id": "eq-0181",
"nomFr": "Combinaison de bacta FlexPoly",
"nomEn": "FlexPoly Bacta Suit",
"effet": "Nécessitant beaucoup moins de volume qu'une cuve de bacta classique tout en préservant un peu plus la pudeur du patient, la combinaison de bacta FlexyPoly de la Zaltin Corp est une petite merveille médicale plutôt marginale. Une série de pompes et de tubes relie cette combinaison transparente à un dispositif volumineux qui mesure la télémétrie sans fil tout en délivrant un bacta synthétique breveté qui circule autour du corps du patient. Le patient reste attaché à un seul endroit tant que la combinaison est utilisée, sous peine d'arracher la tuyauterie de ses raccords et de renverser un précieux bacta au sol. La combinaison procure les mêmes bienfaits de guérison qu'une cuve de bacta.",
