"id": "eq-0183",
"nomFr": "Harnais de contention chimique XV-09",
"nomEn": "XV-09 Chemical Restraint Harness",
"effet": "Le Pacificateur XV-09 est l'un des produits les moins courants vendus par Xenovet. Utiliser un Pacificateur sur un animal sauvage n'est au mieux qu'une solution temporaire, et ne devrait être fait qu'en cas d'urgence. Installer le harnais sur une créature nécessite un test de Survie de difficulté Difficile pour s'assurer que le harnais est correctement ajusté et que l'auto-injecteur est bien positionné. La difficulté de ce test peut être réduite de 1 avec un test de Connaissances (Xénologie) réussi. En cas de réussite, le XV-09 confère deux dés d'aide à tout test de Survie effectué pour contrôler la bête portant le harnais. De plus, les créatures pacifiées avec succès gagnent un dé d'aide à leurs tests de Discipline. Le MJ peut dépenser tout résultat de menace généré par le test de Survie initial pour refléter un ou plusieurs effets secondaires négatifs causés par les drogues. La nature exacte de ces effets secondaires est laissée à la discrétion du MJ. De plus, le MJ peut dépenser trois résultats de menace ou un résultat de désespoir pour refléter une réaction catastrophique aux drogues, comme une crise cardiaque ou un anévrisme cérébral, entraînant la mort de l'animal. Bien que sans danger pour les animaux, le puissant mélange de produits chimiques du harnais peut être dangereux pour l'esprit des êtres sensibles. Attacher le harnais à un être sensible peut entraîner des lésions cérébrales permanentes, voire la mort.",
