"id": "eq-0184",
"nomFr": "Kit vétérinaire portable XV-20",
"nomEn": "XV-20 Portable Veterinary Kit",
"effet": "Le XV-20 est produit par Xenovet, une entreprise biotech basée sur Commenor connue pour ses animaux de compagnie de créateur et sa réputée gamme d'équipement vétérinaire. Le XV-20 fonctionne de manière similaire à une trousse de soins portable, en ce qu'il permet de traiter une créature blessée ou malade sans pénalité. De plus, le kit confère un dé d'aide à tous les tests de Médecine, Survie et Connaissances (Xénologie) effectués pour diagnostiquer ou traiter de tels animaux.",
