"id": "eq-0190",
"nomFr": "Patch de premiers soins",
"nomEn": "Med–Aid Patch",
"effet": "Le terme « premiers soins » désigne globalement des bandages et compresses à usage unique imprégnés de bacta, d'antibiotiques, de coagulants et d'autres agents cicatrisants. Lors d'un test de Médecine visant à soigner les blessures d'un personnage, celui-ci peut dépenser jusqu'à un patch de premiers soins pour ajouter un résultat de réussite et d'avantage automatique au résultat du test. Un personnage ne peut pas utiliser plus d'un patch par test.",
