"nomFr": "Plâtre en spray",
"nomEn": "Spray Plasto-Cast",
"effet": "Immobiliser rapidement une blessure au membre dès qu'elle survient peut éviter que l'extrémité ne soit davantage endommagée par une mauvaise utilisation accidentelle. Un personnage peut effectuer un test de Médecine de difficulté Facile pour appliquer un plâtre en spray sur un membre estropié ou handicapé par une Blessure critique. En cas de réussite, la Blessure critique guérit automatiquement après une semaine de temps narratif.",
