"nomFr": "Sac à dos médical ECM-598 de CAPC",
"nomEn": "CAPC ECM-598 Medical Backpack",
"effet": "Produit par la Chiewab Amalgamated Pharmaceuticals Company à l'usage des forces militaires et des équipes de recherche et sauvetage, l'ECM-598 représente ce qui se fait de mieux en matière d'équipement médical portable. Il permet aux personnages de tenter de soigner autrui grâce à la compétence de Médecine sans pénalité, confère un dé d'aide à tous les tests de Médecine effectués en l'utilisant et, grâce aux tutoriels et informations affichés sur le datapad intégré, réduit d'un cran (jusqu'à un minimum Facile) la difficulté des tests de Médecine pour soigner les Blessures critiques.",
