"nomEn": "Military Traumapac",
"effet": "Équiper chaque soldat d'une trousse médicale complète n'est pas envisageable pour des raisons de poids et de coût, mais SyntheTech/MedTech a optimisé son traumapac pour les milices, mercenaires et forces de défense locales. Un traumapac ne permet au personnage d'utiliser la compétence Médecine que pour tenter de retirer des Blessures critiques à autrui sans pénalité.",
