"id": "eq-0205",
"nomFr": "Stabilisateur cérébral",
"nomEn": "Cerebral Stabilizer",
"effet": "Le stabilisateur cérébral IRAPS de Chiewab est un casque intégral équipé de lignes intraveineuses insérées dans les gros vaisseaux du cou du patient. Il doit être appliqué au patient dans le round suivant une Blessure critique. Ce dispositif peut être utilisé sur un personnage souffrant d'une Blessure critique « Hémorragie » ou « La fin est proche », ou sur un personnage mort au cours du round en cours. L'appliquer nécessite un test de Médecine de difficulté Moyenne. Cela stabilise le personnage, annulant les effets de la Blessure critique tant que l'appareil reste attaché. Si le personnage était mort, il est ramené à la vie, et sa Blessure critique devient une « Blessure affreuse » (avec tous les effets de ce résultat).",
