"nomEn": "Black Melon",
"effet": "Originaire des Étendues de Jundland sur Tatooine, le melon noir possède une coque friable et contient un « lait » consommable. La plupart des humanoïdes trouvent ce lait répugnant, mais il peut fournir une hydratation salvatrice en période de sécheresse ; dans la culture tusken, refuser de le partager est extrêmement insultant (rareté 9 en dehors de Tatooine). Peut être consommé pour repousser la déshydratation. Ceux qui n'en ont jamais bu doivent réussir un test de Résilience de difficulté Difficile, sous peine d'être submergés par le goût infect.",
