"id": "eq-0216",
"nomFr": "Squig chandrilan",
"nomEn": "Chandrilan Squig",
"effet": "Chandrila possède une histoire riche, pleine d'héritage et de coutumes bien établies. Même sa nourriture et ses boissons sont issues d'une longue tradition, et le Squig chandrilan ne fait pas exception. Cocktail à base de fleur de mangue et de whiskwine, cette boisson comprend également des squigs, des anguilles chandrilanes comestibles. L'ajout des squigs fait pétiller et mousser le cocktail, change sa couleur et lui donne une texture agréable à mâcher. Cette boisson est décidément un goût qu'il faut apprendre à apprécier.",
