"nomEn": "Stenness Lizard Pie",
"effet": "Spécialité unique originaire du Nœud de Steness, cette préparation de viande en pâte s'est récemment répandue dans la Bordure extérieure. Malgré des questionnements répétés auprès des habitants du Nœud de Steness, les gastrologues galactiques n'ont pas réussi à déterminer si la Tourte au lézard est destinée aux lézards, ou en contient. Quoi qu'il en soit, le consulat trandoshan de Coruscant a déposé une plainte formelle auprès de l'Agence de sécurité gastronomique de la République. Un personnage ingérant une Tourte au lézard de Stenness subit temporairement 1 point de tension, mais récupère curieusement également 1 blessure.",
