"nomFr": "Anx (outil)",
"nomEn": "Anx (tool)",
"effet": "L'un des outils les plus courants dans la caisse d'un technicien, l'anx sert avant tout à faire levier pour ouvrir et séparer des plaques et panneaux. De la taille approximative d'un avant-bras humain, l'anx a une forme de coin : une poignée épaisse et renforcée s'amincissant vers une lame fine et plate, qui s'insère entre des plaques serrées et les fait sauter bien plus facilement qu'avec d'autres outils. À défaut d'autre chose, certains spationeutes l'ont même utilisé comme arme improvisée, bien qu'il soit peu probable qu'elle soit très efficace.",
