"nomEn": "MicroData P-2 Pocket Attaché",
"effet": "Amélioration du polyvalent Secrétaire de Poche de MicroData et du plus commun datapad Versafunction88, l'Attaché de Poche P-2 offre à son utilisateur un outil administratif portatif polyvalent et un organiseur combinés à une sécurité et un chiffrement de pointe rivalisant avec ceux des services de renseignement impériaux. Modèles incluant : l'Attaché de Poche P-2 de MicroData, le datapad Versafunction108 Traveller. Tenter de s'introduire dans un Attaché de Poche nécessite un test d'Informatique de difficulté Redoutable. En cas d'échec, les données stockées sur l'appareil sont automatiquement effacées et perdues à jamais.",
