"id": "eq-0227",
"nomFr": "Bombonnes de mastic de coque",
"nomEn": "Hull Sealant Canisters",
"effet": "Comme leur nom l'indique, les bombonnes de mastic de coque contiennent du mastic pour coque. Ce produit est sous pression et peut être appliqué sur de petites brèches ou fissures dans la coque d'un vaisseau pour empêcher la perte d'air due au vide. Cette opération nécessite un test de Mécanique réussi, dont la difficulté dépend de la taille du trou. Les trous de plus de trois centimètres de diamètre nécessitent également un matériau supplémentaire, comme une plaque de métal ou de céramique pouvant être fixée à l'aide du mastic.",
