"nomFr": "Bottes-fusées",
"nomEn": "Rocket Boots",
"effet": "La capacité à prendre son envol sans prévenir peut procurer à un combattant un avantage considérable sur un adversaire. Les bottes-fusées permettent à une personne de fonctionner comme un véhicule de gabarit 1, vitesse 1, maniabilité –3, seuil de tension système 4 ou 3, ne pouvant opérer qu'en atmosphère et nécessitant la compétence Pilotage (Planétaire). À la fin de chaque round d'utilisation, les bottes-fusées subissent 1 point de tension système à mesure que leur carburant s'épuise.",
