"effet": "Bien que construites autour de datapads courants, les boussoles urbaines sont des outils plus spécialisés. Les individus utilisant une boussole urbaine pour se repérer en ville retirent deux dés de complication aux tests dus à la méconnaissance de la ville, au trafic, ou à d'autres dangers de déplacement évitables. De plus, une boussole urbaine peut fournir des informations sur les établissements et coutumes locaux, accordant un dé d'aide aux tests visant à trouver des informations sur le fonctionnement de la ville, ses lieux remarquables et ses commerces de toutes sortes.",
