"nomFr": "Datapad « Mercantiler » MDD-12",
"nomEn": "MDD-12 \"Mercantiler\" Datapad",
"effet": "Produit par MerenData pour répondre à une forte demande de la clientèle, le MDD-12 est une version moins puissante et moins polyvalente du système informatique Mercantiler embarqué équipant les droïdes de commerce de la série Exchequer de MerenData. Utilisé dans la région pour laquelle il est programmé — Mondes du Noyau, Bordure intérieure, Bordure médiane ou territoires spécifiques de la Bordure extérieure —, le datapad Mercantiler confère un dé d'aide à tout test de Négociation effectué pour acheter ou vendre des biens. Ces datapads n'accordent aucun bonus en dehors de leur région spécifique.",
