"id": "eq-0243",
"nomFr": "Gantelets de liaison verpins",
"nomEn": "Verpine Bond Gauntlets",
"effet": "Les gantelets de liaison sont une invention verpine conçue pour renforcer et raidir les avant-bras d'un individu, tout en stabilisant les mouvements de la main et du bras. Grâce à cette stabilité supplémentaire, les gantelets de liaison verpins confèrent à leurs utilisateurs un dé d'aide aux tests effectués pour manipuler des matériaux volatils ou effectuer un travail délicat. De telles circonstances doivent être arbitrées par le MJ au cas par cas, et peuvent inclure des tests d'Informatique et de Mécanique pour effectuer des réparations délicates, ainsi que des tests de Roublardise pour crocheter des serrures ou désamorcer des pièges.",
