"id": "eq-0244",
"nomFr": "Guide de l'initié",
"nomEn": "Insider's Guide",
"effet": "Les voyageurs aguerris savent éviter les pièges à touristes évidents et trouver les établissements fréquentés par les habitants, mais se renseigner sur des besoins particulièrement inhabituels éveille parfois les soupçons. Modèles incluant : les Guides de la Galaxie de Vlaso. Un personnage utilisant un guide de l'initié ajoute un résultat d'avantage automatique à tout test visant à trouver un lieu ou un service précis dans la région couverte par le guide.",
