"id": "eq-0247",
"nomFr": "Holo-lunettes d'apprentissage",
"nomEn": "Hologoggles",
"effet": "L'apprentissage est bien plus efficace lorsqu'il intègre un temps de pratique dédié. Lors de l'achat d'une paire de holo-lunettes, le personnage choisit une compétence hors-combat. Cette compétence devient une compétence de carrière tant que le personnage possède les lunettes (à la discrétion du MJ, elles doivent toutefois être portées plusieurs heures par jour pendant plusieurs mois pour obtenir ce bonus). Un personnage ne peut bénéficier que d'une seule paire de holo-lunettes à la fois ; pour changer de compétence, il doit se débarrasser de la paire actuelle et en acheter une nouvelle.",
