"id": "eq-0257",
"nomFr": "Lunettes de données",
"nomEn": "Data Goggles",
"effet": "Ces lunettes superposent au champ de vision du porteur des informations supplémentaires. Au début d'une rencontre, un personnage peut choisir une compétence de Connaissances. Pour le reste de la rencontre, il ajoute un résultat de succès automatique à tous les tests effectués avec cette compétence tant qu'il porte les lunettes de données. Le MJ peut décider qu'un personnage doit d'abord obtenir des fichiers de données spécialisés à charger dans les lunettes avant de pouvoir les utiliser.",
