"id": "eq-0259",
"nomFr": "Lunettes de visée AG/1 Mk III",
"nomEn": "AG/1 Mk III Targeting Goggles",
"effet": "Appréciées des servants d'armes, des tireurs d'appui et de quiconque vit derrière le viseur d'une arme portable lourde ou montée sur véhicule, les lunettes de visée AG/1 Mk III de Farbitech sont l'aide à la visée la plus vendue du marché galactique. Porter des lunettes de visée AG/1 ou AG/L Mk III permet au personnage de compter le gabarit de sa cible comme supérieur d'un cran lors des tests d'Artillerie contre un vaisseau ou un véhicule.",
