"nomFr": "Manuel de campagne militaire",
"nomEn": "Military Field Manual",
"effet": "Des manuels complets délivrés aux soldats réguliers aux publications clandestines instruisant les combattants de la résistance à la guérilla, on trouve des manuels de campagne partout où des troupes sont présentes. Modèles incluant : le Manuel de campagne de l'Armée impériale FM-5-31 (Pièges), le Manuel du Rebelle du Général Airen Cracken. Selon le manuel, une fois par scène, un personnage peut utiliser les informations qu'il contient pour obtenir un dé d'aide à n'importe quelle tâche, à la discrétion du MJ.",
