"nomFr": "Pince à répulsion",
"nomEn": "Repulsor Clamp",
"effet": "Cette pince pneumatique, fixée à un moteur à répulsion, permet aux Techniciens de maintenir des objets lourds en l'air pendant qu'ils effectuent des réparations. Une pince à répulsion peut maintenir en suspension un objet unique de 10 points d'encombrement ou moins. De plus, disposer d'une pince à répulsion retire un dé de complication aux tests visant à réparer des traumatismes de coque et des Coups critiques sur les vaisseaux et véhicules.",
