"nomEn": "\"Rider\" Ascension Pistol",
"effet": "Certains individus aiment modifier leurs armes de poing standards avec des grappins, mais Merr-Sonn a trouvé une clientèle dédiée préférant des dispositifs spécialisés ne nécessitant aucun temps de préparation. En tant qu'action, un personnage peut effectuer un test de Distance (Léger) de difficulté Moyenne pour tirer le grappin sur un objet jusqu'à portée moyenne. Lors d'une action ultérieure, il peut enrouler le câble, se hissant vers l'objet cible (ou, si l'objet n'est pas fixé et plus léger que lui, en attirant l'objet vers le personnage). Un personnage utilisant un pistolet d'ascension pour se hisser lui-même et un autre personnage doit réussir un test d'Athlétisme de difficulté Moyenne pour éviter de perdre sa prise sur son partenaire ou sur l'arme.",
