"nomFr": "Sacoche d'agent",
"nomEn": "Agent's Bag",
"effet": "Terme générique désignant les divers paquets confidentiels, sacoches de courrier et mallettes que les agents du renseignement modifient pour leurs missions sur le terrain. Les caractéristiques exactes d'une sacoche d'agent varient selon l'agence et l'agent, et sont laissées à la discrétion du MJ. Elle peut recevoir diverses modifications d'équipement ; joueurs comme MJ sont encouragés à en créer de nouvelles pour personnaliser la sacoche.",
