"id": "eq-0275",
"nomFr": "Scanner de fret",
"nomEn": "Cargo Scanner",
"effet": "Pour les contrebandiers et les commerçants indépendants, l'humble scanner de fret est tout aussi utile qu'un blaster, sinon plus. Modèles inclus : le scanner de fret Fabritech A-11. Un personnage utilisant un scanner de fret peut réussir un test d'Informatique de difficulté Moyenne pour augmenter de 10 % (arrondi au supérieur) la capacité d'encombrement disponible d'un véhicule planétaire ou d'un vaisseau de gabarit 3 ou plus, grâce à une organisation plus efficace.",
