"effet": "Sans doute le moyen le plus courant de tricher au sabacc, un skifter est une carte truquée. Modèles incluant : de nombreuses variantes. Lorsqu'il joue, un personnage utilisant un skifter gagne un dé d'aide aux tests de Roublardise pour tricher.",
