"id": "eq-0278",
"nomFr": "Speeder à pied",
"nomEn": "Foot Speeder",
"effet": "Ces curieux engins combinent la rapidité d'un speeder avec une facilité de rangement et une construction simple qui rendent leur entretien bien moins coûteux que celui d'un véritable véhicule. Un speeder à pied permet à une personne de fonctionner comme un véhicule de Gabarit 1, Vitesse 1, Maniabilité –1, Seuil de fatigue système 4, ne pouvant opérer qu'en atmosphère et nécessitant du Pilotage (Planétaire). Son plafond de vol est de cinq mètres.",
