"id": "eq-0281",
"nomFr": "Trousse à outils de démolition",
"nomEn": "Demolitions Tool Kit",
"effet": "Élément essentiel de l'équipement de tout artificier spécialisé dans le déminage (EOD), cette trousse est petite (environ treize centimètres de long une fois fermée) et fabriquée dans des matériaux non réactifs et non conducteurs. Elle compte comme une trousse à outils pour les tests liés à la préparation, la pose ou le désamorçage d'explosifs. Lors de ces tests, l'utilisateur peut dépenser quatre résultats d'avantage pour retirer un résultat de désespoir.",
