"nomFr": "Unité d'assistance à répulsion",
"nomEn": "Repulsor Assist Unit",
"effet": "Certains modèles de grappins et de harnais d'escalade reposent sur des forces autres que la pure force musculaire pour fonctionner. Un personnage utilisant une unité d'assistance à répulsion réduit de 2 la difficulté pour grimper (jusqu'à un minimum de 0). Une unité d'assistance à répulsion peut également être fixée à une cargaison pour réduire sa valeur d'encombrement de 7.",
