"nomEn": "BlasTech Model 58 Concealment Holster",
"effet": "Ces étuis compacts conçus pour de petites armes de poing légères épousent les contours du corps du porteur et masquent leur présence, même face à une observation ou une surveillance déterminée. Ils ajoutent un dé de complication aux tests de Perception visant à découvrir l'arme dissimulée, mais ne peuvent contenir que des pistolets blaster légers ou des blasters de dissimulation.",
