"nomFr": "Matériel de piratage",
"nomEn": "Slicer Gear",
"effet": "Les pirates informatiques, ces talentueux jockeys de l'informatique qui naviguent dans les entrailles labyrinthiques du code et des systèmes centraux aussi aisément qu'un pilote d'élite traverse une ceinture d'astéroïdes, utilisent du matériel spécialement conçu pour accéder à des systèmes informatiques sécurisés. Modèles incluant : divers modèles uniques, de nombreuses variantes.",
