"id": "eq-0301",
"nomFr": "Pompe saline",
"nomEn": "Saline Pump",
"effet": "Les Clawdites ajustent leur forme en déplaçant du fluide à travers leur corps, et en réorganisant les structures à la surface de leur peau. Un Clawdite portant une pompe saline peut augmenter ou diminuer sa masse et sa taille jusqu'à un dixième, lui permettant de se métamorphoser en une gamme de formes plus large. Ajoute un dé d'aide aux tests du Clawdite pour se faire passer pour une autre personne grâce à sa capacité d'espèce, et ajoute un dé de complication aux tests des autres personnages visant à percer sa tromperie physiologique. Les non-Clawdites ne tirent aucun bénéfice de cet objet pour se déguiser (et le trouveraient probablement extrêmement inconfortable à utiliser).",
