"id": "eq-0313",
"nomFr": "Anneaux-énigmes thisspiasiens",
"nomEn": "Thisspiasian Puzzle Rings",
"effet": "Ces anneaux ressemblent à un nid de serpents, tordus et entrelacés, se mordant la queue. Pour tenter de résoudre l'énigme, un personnage doit y consacrer au moins une heure et réussir un test de Discipline de difficulté Difficile. En cas d'échec, il soigne 2 points de tension. En cas de réussite, le personnage a une vision, apprenant une chose le concernant qui pourrait (à la discrétion du MJ) se produire dans la semaine suivante. Une fois résolus, les anneaux-énigmes se désagrègent, leur lien avec la Force étant épuisé. Pour obtenir une nouvelle vision, le PJ doit se procurer un nouveau jeu d'anneaux.",
