"id": "eq-0338",
"nomFr": "Équipement de géomètre",
"nomEn": "Surveyor's Equipment",
"effet": "La première étape pour construire quoi que ce soit sur une planète est un bon relevé topographique, aussi la plupart des ingénieurs militaires et éclaireurs longue distance sont-ils formés à l'équipement facilitant cette tâche. L'équipement de géomètre ajoute deux dés d'aide aux tests de Perception d'un personnage lorsqu'il détermine des emplacements à la surface d'une planète, mesure des distances, planifie des colonies ou bases, ou crée des cartes planétaires détaillées.",
