"nomEn": "Microdroid Listener",
"effet": "Ces minuscules automates arachnéens, à peine plus que des micros mobiles, méritent à peine le nom de « droïde ». Placer ce dispositif sans être remarqué nécessite un test opposé de Roublardise contre Vigilance. Une fois le mouchard en place, un personnage doit réussir un test de Vigilance de difficulté Redoutable pour le localiser, même en le cherchant spécifiquement. Le micro-droïde ne dispose d'aucune capacité d'autodéfense ou d'évasion, bien que certains fabricants équipent leurs modèles d'une autodestruction en cas de trafouillage.",
