"nomEn": "Surveillance Scanner",
"effet": "Les scanners de surveillance sont des appareils portatifs utilisés pour détecter les systèmes de surveillance actifs et passifs. Ils ont une portée courte à l'échelle planétaire ou longue à l'échelle personnelle. Utiliser un scanner de surveillance améliore une fois la capacité de tout test effectué pour localiser des mouchards, ratisser des pièces à la recherche de caméras cachées, capter des flux de données, ou entreprendre toute autre activité de contre-surveillance.",
