"nomFr": "Balise de secours",
"nomEn": "Rescue Beacon",
"effet": "Un objet essentiel pour quiconque explore les terres sauvages des mondes de la Bordure extérieure. Les balises de secours portables se portent au poignet ou à la ceinture et émettent un signal de localisation vers un autre appareil, garantissant que l'emplacement de la balise et de son porteur soit toujours connu. Les unités bon marché peuvent émettre un signal toutes les 30 minutes et localiser la balise dans un rayon de 3 km. Les modèles plus onéreux fournissent une localisation précise et actualisée en temps réel. Les balises de secours peuvent également être câblées directement dans certains modèles de droïdes.",
"cout": 200,
