"nomFr": "Cocon environnemental Czerka BC-7",
"nomEn": "Czerka BC-7 Environmental Cocoon",
"effet": "Principalement destiné aux chasseurs et survivalistes, un cocon environnemental offre un espace sécurisé dans un lieu autrement hostile. Le cocon réduit de trois la difficulté des tests de Résilience effectués pour résister aux effets d'un froid ou d'une chaleur extrême. Il retire également jusqu'à trois dés de complication ajoutés aux tests à cause d'une chaleur ou d'un froid extrême, tant que l'utilisateur reste à l'intérieur.",
