"nomEn": "Condenser Unit",
"effet": "Les condenseurs utilisent une technologie de vaporateur pour fournir à la fois de l'eau fraîche et une source de chaleur sans fumée en un seul appareil portable. Modèles inclus : le vaporateur portable SurvivalGear, le condenseur de poche TaggeCo. Un condenseur peut recueillir suffisamment d'eau chaque jour pour subvenir aux besoins d'un seul individu, et sa cellule d'énergie dure environ six mois.",
