"id": "eq-0371",
"nomFr": "Cuisine de campagne Survival Equipment Inc.",
"nomEn": "Survival Equipment Inc. Field Kitchen",
"effet": "Moyen ingénieux de se nourrir en pleine nature, la Cuisine de campagne est la dernière offre de SurvivalEquipment Inc. Installer une cuisine de campagne prend environ trente minutes standard. Grâce à sa conception efficace et aux informations incluses dans le datapad, utiliser une cuisine de campagne accorde deux dés d'aide à tout test de Survie ou d'Éducation effectué pour stocker, identifier, cuisiner ou stériliser des denrées (et peut, à la discrétion du MJ, permettre de rendre comestibles des aliments qui ne le seraient normalement pas).",
