"id": "eq-0376",
"nomFr": "Générateur de biome personnalisé A99",
"nomEn": "A99 Custom Biome Generator",
"effet": "Tri-Planetary Atmospherics (TPA) est une petite entreprise de recherche et d'ingénierie atmosphérique basée dans les Territoires de la Bordure extérieure. Équipé d'analyseurs et de synthétiseurs chimiques puissants, l'A99 peut produire des environnements confortables et sûrs, même pour les exigences biologiques les plus contraignantes. Une fois installé, il est généralement intégré aux systèmes de ventilation et de régulation thermique existants, ce qui lui permet de reproduire quasiment n'importe quel biome de l'univers.",
