"nomFr": "Kit de survie en milieu sauvage",
"nomEn": "Wilderness Survival Kit",
"effet": "Les kits de survie en milieu sauvage sont une précaution nécessaire pour ceux qui voyagent régulièrement à travers des zones inhospitalières. Modèles incluant : le WanderKit Pretormin Environmental. La plupart des kits de survie comprennent une cape thermique, un multi-outil ou couteau de survie, une balise de détresse, deux comlinks d'urgence, une bobine de fil, des barres de rations, un medpac basique, deux respirateurs, une gourde avec filtre, un glow rod, cinquante mètres de ligne en microfibre haute résistance, dix paquets de rations, et un pistolet lance-fusées d'urgence.",
