"id": "eq-0381",
"nomFr": "Kit de survie post-crash",
"nomEn": "Crash Survival Kit",
"effet": "Répandu chez les pilotes et équipages de véhicules, le kit de survie post-crash est une précaution nécessaire pour ceux qui voyagent régulièrement à travers des zones inhospitalières. Modèles inclus : le kit de survie post-crash Pretormin Environmental. La plupart des kits comprennent un manteau thermique, un multi-outil ou un couteau de survie, une balise de détresse, deux comlinks d'urgence, une bobine de fil, des barres de rationnement, un medpac basique (équivalent au Medpac d'urgence GLiS), deux respirateurs, un jerricane d'eau avec filtre, une torche, cinquante mètres de câble microfibre à haute résistance, dix rations de terrain, et un pistolet lance-fusées d'urgence. Les pilotes militaires, contrebandiers et chasseurs de primes y ajoutent souvent un pistolet blaster compact.",
