"id": "eq-0383",
"nomFr": "Leurre chimique Beastmaster",
"nomEn": "Beastmaster Chem Lure",
"effet": "Grâce à des phéromones, le leurre chimique Beastmaster de CorChemCo attire les bêtes vers un endroit où elles peuvent être facilement capturées ou tuées. Les créatures ciblées doivent réussir un test de Discipline de difficulté Difficile pour résister à l'envie de venir enquêter rapidement. Cet équipement est souvent utilisé avec des électro-pièges ou d'autres dispositifs de capture pour attraper des animaux exotiques destinés à devenir animaux de compagnie, pensionnaires de zoo ou sujets de recherche. Utiliser le Beastmaster ne nécessite pas de test de compétence, bien que le placer au meilleur endroit puisse, à la discrétion du MJ, nécessiter un test de Survie.",
