"id": "eq-0389",
"nomFr": "Poids d'entraînement",
"nomEn": "Training Weights",
"effet": "De nombreux Guerriers portent des bracelets ou chevillères lestés lors de leur entraînement. Modèles incluant : le système TruFit de TaggeCo, le Smart-trainer M2 de Sidyne. Un personnage portant un ou plusieurs poids d'entraînement ajoute un dé de complication à tous les tests basés sur la Vigueur et l'Agilité, ainsi qu'à tous les tests de combat. Si un personnage porte des poids d'entraînement tout au long d'une session de jeu, augmentez de 1 le montant de PX qu'il reçoit pour la session. À la discrétion du MJ, un personnage portant des poids d'entraînement pourrait ne pas recevoir ce PX supplémentaire s'il n'a effectué aucun test affecté par les poids durant la session.",
