"id": "eq-0390",
"nomFr": "Processeur atmosphérique Elysium Modèle 2",
"nomEn": "Elysium Model 2 Atmospheric Processor",
"effet": "Gandorthral Atmospherics est un fournisseur de premier plan de systèmes d'ingénierie atmosphérique, produisant de tout, des masques et respirateurs aux combinaisons pour environnements hostiles, en passant par d'immenses installations de terraformation de la taille d'une ville (l'encombrement indiqué correspond à l'installation non assemblée). Alimenté par la chaleur et l'énergie naturelles du sous-sol d'une planète, le Modèle 2 ressemble à un immense ziggourat : une pyramide étagée au sommet plat, remplie de systèmes conçus pour produire des atmosphères respirables, de l'eau potable, et même des phénomènes météorologiques à partir des matières premières disponibles. À peu près de la taille d'un croiseur stellaire, il nécessite un équipage d'au moins cent ingénieurs et techniciens, sans compter les nombreux droïdes affectés aux zones inadaptées à leurs collègues organiques.",
