"nomFr": "Répulseur sonique",
"nomEn": "Sonic Stormer",
"effet": "Conçus principalement à l'intention des éclaireurs et des chasseurs, les répulseurs soniques ont également été adaptés pour un usage dans les colonies et campements des régions reculées. Une fois activés, ces appareils soniques de la taille d'une main génèrent des ondes sonores à haute fréquence, inaudibles pour les humains et de nombreuses espèces extraterrestres, qui repoussent la plupart des créatures et bêtes à proximité avant qu'elles ne deviennent une menace. Bien que très utiles, certaines créatures - en particulier les prédateurs les plus tenaces - peuvent être mises en rage par certains sons générés par le répulseur sonique (ce qui peut survenir immédiatement ou après une exposition prolongée, selon la créature).",
