"id": "eq-0411",
"nomFr": "Clôture périmétrique électrique portable",
"nomEn": "Portable Electric Perimeter Fence",
"effet": "Fabriquées par de nombreux constructeurs à travers la galaxie, les clôtures périmétriques électriques portables utilisent des faisceaux d'énergie cohérente pour créer une barrière protectrice autour de campements, avant-postes ou toute autre zone sensible nécessitant une sécurité supplémentaire. Quiconque entre en contact avec une clôture périmétrique électrique portable subit les effets d'une grenade paralysante.",
