"id": "eq-0415",
"nomFr": "Collier de sécurité",
"nomEn": "Security Collar",
"effet": "Plus connus sous le nom de colliers d'esclave, les colliers de sécurité utilisés par les esclavagistes thalassiens sont des équipements technologiquement sophistiqués malgré leur fonction simple. Retirer en toute sécurité un collier de sécurité thalassien sans la clé appropriée nécessite un test de Roublardise de difficulté Redoutable. En cas d'échec, le porteur subit 2 points de tension et 1 blessure (ceci ignore l'absorption) et devient désorienté pendant cinq rounds.",
