"nomFr": "Collier paralysant",
"nomEn": "Stun Collar",
"effet": "Les esclavagistes et propriétaires d'esclaves ne maintiennent pas toujours leurs esclaves enchaînés pendant qu'ils vaquent à leurs occupations. Activé à distance, le collier paralysant délivre à son porteur une décharge à haute tension, infligeant dix dégâts d'Étourdissement. Cependant, le collier peut également être utilisé à des fins létales, infligeant douze dégâts et provoquant une Blessure critique en ajoutant +20 au jet. Un test de Mécanique de difficulté Difficile est nécessaire pour retirer le collier sans électrocuter son porteur.",
