"nomEn": "AL-DR8 Grav-Binders",
"effet": "Conçues pour maîtriser les individus particulièrement insaisissables, les entraves gravitationnelles utilisent une technologie de micro-répulsion pour appliquer artificiellement les effets d'une gravité extrême à un captif. Se libérer d'entraves gravitationnelles nécessite un test d'Athlétisme de difficulté Redoutable (les effets contraignants de la gravité artificiellement accrue sur tout le corps empêchent de s'en défaire par la seule souplesse).",
