"effet": "Une fois un prisonnier capturé, il doit souvent être entravé. Se libérer de menottes paralysantes nécessite un test d'Athlétisme ou de Coordination de difficulté Redoutable. Le MJ peut dépenser deux résultats de menace ou un résultat de désespoir sur le test pour faire subir au personnage 4 points de tension (ceci ignore l'absorption). De même, un personnage tenant la télécommande associée peut activer les menottes paralysantes pour infliger 4 points de tension.",
