"id": "eq-0421",
"nomFr": "Nano-droïdes",
"nomEn": "Nano-droids",
"effet": "Ces machines microscopiques prennent généralement la forme de sphères, invisibles à l'œil nu, conservées dans une suspension de fluide de transfert électrolytique. Elles ajoutent trois dés de complication aux tests de Perception d'un personnage cherchant à les remarquer, à moins que le chercheur ne sache qu'il faut les repérer et dispose d'un scanner approprié. Les nano-droïdes peuvent être reprogrammés pour exploser. Une fois activés, ils infligent 20 dégâts avec la qualité Brèche 1 à tout ce qui se trouve à portée courte, y compris l'objet qui les contenait.",
