"nomFr": "Transpondeur personnel",
"nomEn": "Personal Transponder",
"effet": "Les transpondeurs personnels sont des dispositifs de repérage à faible puissance utilisés pour localiser des individus. Capter le signal d'un transpondeur personnel avec suffisamment de précision pour en trouver l'emplacement exact à portée courte à l'échelle planétaire nécessite un test d'Informatique de difficulté Moyenne. Augmentez la difficulté de ce test de deux pour chaque bande de portée planétaire au-delà de la portée courte, jusqu'à un maximum de portée extrême à l'échelle planétaire.",
