"effet": "Les Commandants de l'Alliance sont issus de nombreuses cultures humaines, quasi-humaines et extraterrestres à travers la galaxie. Quelle que soit la forme que prend l'objet, les Commandants portant un symbole de commandement ajoutent un dé d'aide à tous les tests de compétences Sociales effectués pour interagir avec d'autres personnes issues de leur culture militaire particulière.",
