"id": "eq-0450",
"nomFr": "Booster bleu (conteneur cargo de 100 doses)",
"nomEn": "Booster Blue (100 Dose Cargo Container)",
"effet": "Dérivé d'un colorant industriel utilisé dans les grands travaux de construction, notamment la fabrication de vaisseaux, le booster bleu est une drogue dopante prisée des pilotes et des tireurs. Restrictions : le booster bleu est illégal sur la plupart des mondes. Un personnage sous l'effet du booster bleu peut majorer une fois l'aptitude d'un test d'Agilité, d'Intellect ou de Ruse qu'il entreprend, reflétant sa concentration et son acuité mentale accrues. Cependant, cette concentration artificielle a un coût : le personnage ne peut retirer aucune fatigue à la fin des scènes ou rencontres pour le reste de la session. Les effets bénéfiques du booster bleu durent une scène ou une rencontre de combat.",
