"nomEn": "Death Sticks (100 Dose Cargo Container)",
"effet": "Les bâtonnets de la mort sont une création peu ragoûtante dérivée du champignon balo de la planète Balosar, distribuée sous forme liquide dans de petits bâtonnets rouges et jaunes distinctifs. Restrictions : ce sont des substances contrôlées sur la plupart des mondes, et au minimum, les mineurs ne peuvent pas en acheter ; ils sont totalement illégaux sur de nombreux autres mondes, en particulier ceux appliquant des normes sanitaires strictes. Les effets à court terme d'une seule dose durent une scène ou une rencontre de combat, ajoutent un dé de complication à toute tâche entreprise par le personnage, et peuvent, à la discrétion du MJ, réduire d'une certaine façon sa connexion à la Force.",
