"id": "eq-0454",
"nomFr": "Glitterstim (conteneur cargo de 100 doses)",
"nomEn": "Glitterstim (100 Dose Cargo Container)",
"effet": "Le glitterstim est une variété d'épice extrêmement rare, raffinée à partir des toiles tissées par les araignées énergétiques de Kessel et extraite par les malheureux esclaves envoyés dans ces profondeurs obscures. Restrictions : le glitterstim est illégal sur la plupart des mondes, et son commerce est activement surveillé et contrôlé par les autorités impériales. C'est une drogue hautement addictive aux propriétés hallucinogènes : sa consommation ajoute trois dés d'aide à tous les tests de Perception et de Vigilance pour le reste de la scène. Certains utilisateurs rapportent également des capacités télépathiques temporaires, que le MJ peut accorder à sa discrétion.",
