"id": "eq-0457",
"nomFr": "Lesai (module de fret hermétique de 20 doses)",
"nomEn": "Lesai (20 Dose Enviro-Sealed Cargo Pod)",
"effet": "Le lesai est une variété d'épice qui n'est pas extraite du sol, mais cultivée sous forme de champignon présent uniquement sur certains lézards des planètes Zebitrope IV et VIII. Restrictions : le lesai est illégal sur la plupart des mondes à forte présence impériale. Un personnage qui consomme du lesai au moins une fois toutes les vingt-quatre heures n'a pas besoin de dormir et ne subit aucune pénalité ni tension liée au manque de sommeil. Il peut retirer sa tension comme s'il avait dormi une nuit complète après toute période de huit heures ou plus sans activité stressante (combat, effort mental intense, discussion à forte charge émotionnelle). Le seul effet secondaire notable du lesai est de laisser d'étranges taches violettes aux endroits où il est appliqué. Si un personnage sous l'effet du lesai passe vingt-quatre heures complètes sans nouvelle dose, il lui devient de plus en plus difficile de rester éveillé jusqu'à ce qu'il en reprenne ou dorme. Certains officiels impériaux affirment que le lesai transforme ses utilisateurs en monstres amoraux dénués de sentiments ou de compassion ; la véracité de cette affirmation est laissée à la discrétion du MJ, qui peut choisir de garder sa décision secrète vis-à-vis des joueurs dont les personnages consomment du lesai.",
