"effet": "Depuis des temps immémoriaux, l'épice appelée yarrock est produite sur Iridonia, créée par leurs chamans pour conférer à leurs guerriers une plus grande clarté d'esprit et une détermination martiale. Restrictions : le yarrock est assez rare, et peu de planètes réglementent donc explicitement son usage, les seules cargaisons transitant par des trafiquants du marché noir. Le yarrock dure le temps d'une scène. Un personnage sous l'effet du yarrock n'a besoin d'effectuer aucun test de Peur ; il est considéré comme réussissant automatiquement. Cependant, une fois qu'il a consommé du yarrock, il doit également ajouter un dé de complication à tout test lié à la Volonté ou à la Prestance pour le reste de la session.",
