"nomEn": "Avabush Spice (100 Dose Cargo Container)",
"effet": "L'épice avabush est une drogue qui induit relaxation et léthargie ; certains l'utilisent comme somnifère illicite. Restrictions : l'épice avabush est interdite ou contrôlée sur la plupart des mondes à forte présence impériale. Un personnage ayant consommé de l'épice avabush se sent léthargique et ne peut majorer qu'un seul dé d'aptitude en dé de maîtrise sur un test donné, du fait de cette torpeur mentale. De plus, chaque fois que ce personnage tente intentionnellement de mentir ou de dissimuler la vérité, le MJ majore un dé de difficulté en dé de contrainte. Les effets de l'épice avabush durent une scène ou une rencontre de combat.",
