"nomFr": "Fusées éclairantes solaires",
"nomEn": "Sun Flares",
"effet": "Courantes dans chaque kit de survie jedi et paquetage d'urgence de pilote de cette époque, les fusées éclairantes solaires servent à signaler en l'absence de communications. Lorsqu'elles détonnent, elles répandent un composé lumineux sur une large zone d'impact, illuminant complètement la zone (transformant efficacement les zones sombres en l'équivalent d'un plein jour). Une fusée éclairante solaire est pratique pour illuminer des points cibles pour l'artillerie de blaster, ainsi que pour attirer l'attention de vaisseaux de secours (les fusées éclairantes solaires sont souvent utilisées par les pilotes abattus). Elles existent en différentes couleurs, afin que leur signification puisse être comprise rapidement, le rouge étant le signe universel de détresse.",
