"nomEn": "DefenStar Ltd. Nyalsan II Planetary Shield Generator",
"effet": "DefenStar Ltd. produit un certain nombre de générateurs de boucliers planétaires conçus pour protéger tout, des petits campements de la taille d'un peloton aux immenses garnisons avancées abritant des milliers de soldats, de personnel et d'armes. Le Nyalsan II confère une défense à distance de 2 à chaque quadrant (nord, sud, est, ouest) d'une base. Les points de défense à distance peuvent être réaffectés à différents quadrants par l'équipage du générateur selon les besoins, d'une manière similaire à la manœuvre Réorienter les boucliers déflecteurs.",
