"nomEn": "X5R Heavy Demolitions Kit",
"effet": "Le lourd étui en carbo-plas d'un kit de démolition X5R est rempli de minuteries de précision, de détonateurs à distance, et d'autres outils essentiels du métier pour un expert en explosifs dévoué. L'utilisateur d'un kit X5R gagne deux dés d'aide aux tests de Mécanique pour préparer, poser ou désamorcer des explosifs. De plus, une fois par session, un personnage utilisant un X5R peut retirer un résultat de désespoir ou jusqu'à trois résultats de menace (après annulation des symboles de dés mais avant résolution de l'effet) d'un test de Mécanique lié à des explosifs.",
